using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B3RepairState {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 required");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B3_StructureRepair/"));var root=s.GetRootGameObjects().Single(g=>g.name=="B3_Circular_SampleFloor").transform;var plan=JObject.Parse(File.ReadAllText(h+"layout_after.json"));var bad=plan["placements"].Where(q=>{var g=root.Find("B3_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);if(!g||!g.gameObject.activeInHierarchy)return true;var p=q["position"];return Vector3.Distance(g.localPosition,new Vector3((float)p[0],(float)p[1],(float)p[2]))>.001f||Quaternion.Angle(g.localRotation,Quaternion.Euler(0,(float)q["yaw"],0))>.01f;}).Select(q=>(string)q["name"]).ToArray();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToDictionary(t=>GlobalObjectId.GetGlobalObjectIdSlow(t).ToString());var before=JArray.Parse(File.ReadAllText(h+"state_before.json"));var missing=before.Where(q=>!all.ContainsKey((string)q["id"])).Select(q=>(string)q["path"]).ToArray();var result=new{placements=plan["placements"].Count(),placementErrors=bad,originalTransforms=before.Count,missingOriginalTransforms=missing,scene=s.path,saved=!s.isDirty};File.WriteAllText(h+"scene_state_result.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
